INSERT INTO `notices` VALUES (1,'Campus Cleanup Drive','Join us for the annual campus cleanup this Saturday, April 27. Gloves and tools provided. Meet at the main gate at 8 AM.','2025-04-20 10:00:00'),(2,'New Cafeteria Menu','Starting next week, enjoy a healthier and more diverse menu at the student cafeteria. Feedback is welcome!','2025-04-19 14:15:00'),(3,'Summer Internship Fair','Don’t miss the Internship Fair on May 3 at the main hall. Meet recruiters from top companies. Bring your CV!','2025-04-18 09:30:00'),(4,'Blood Donation Camp','Red Cross is organizing a blood donation camp on campus on April 30. Free snacks and certificates for donors.','2025-04-17 11:00:00'),(5,'AI Workshop Registration','Limited seats left for the AI & Machine Learning workshop on May 10. Register online through the student portal.','2025-04-15 15:45:00'),(6,'Library Book Return Notice','Reminder: All borrowed books must be returned by May 5 to avoid late fees. Check your library account for due dates.','2025-04-16 13:00:00'),(7,'Sports Fest 2025','Annual Sports Fest begins on May 12. Register your teams by April 28. Trophies and prizes await the champions!','2025-04-14 08:50:00');
